import {useSearchParams} from '@github-ui/use-navigate'
import {PrevNextPagination} from '@github-ui/code-scanning-shared/components/PrevNextPagination'
import type {Cursor} from '@github-ui/code-scanning-shared/types/cursor'
import {Heading, Label} from '@primer/react'

import type {PublicMonitoringPayload} from '../types'
import {AlertList} from './AlertList'

export function PublicMonitoringPage({
  payload,
  ownerType,
  name,
}: {
  payload: PublicMonitoringPayload
  ownerType: 'business' | 'org'
  name: string
}) {
  const [, setParams] = useSearchParams()

  function handleCursorChange(cursor: Cursor) {
    window.scrollTo(0, 0)
    const value = 'after' in cursor ? cursor.after : cursor.before
    setParams(prev => {
      const next = new URLSearchParams(prev)
      next.set('cursor', value)
      return next
    })
  }

  const ownerNoun = ownerType === 'business' ? 'enterprise' : 'organization'

  return (
    <div>
      <div className="d-flex flex-items-center gap-2 tmp-mb-1">
        <Heading as="h1">Public monitoring</Heading>
        <Label variant="success">Preview</Label>
      </div>
      <p className="color-fg-muted tmp-mb-3">
        GitHub monitors secrets leaked across GitHub in real time. These findings may be associated with your{' '}
        {ownerNoun}.
      </p>
      <AlertList payload={payload} ownerName={name} />
      <PrevNextPagination
        nextCursor={payload.nextCursor}
        prevCursor={payload.previousCursor}
        onCursorChange={handleCursorChange}
      />
    </div>
  )
}
