import {ActionList, ActionMenu, IconButton, Link} from '@primer/react'
import {KebabHorizontalIcon} from '@primer/octicons-react'
import {CopyToClipboardButton} from '@github-ui/copy-to-clipboard/Button'
import {blobPath, commitPath, blamePath} from '@github-ui/paths'

import type {LocationCardLocation} from './types'
import {CodeSnippet} from './CodeSnippet'
import {CommitFooter} from './CommitFooter'
import styles from './LocationCard.module.css'

export interface LocationCardProps {
  location: LocationCardLocation
  ownerName: string
  repoName: string
  enableLinks?: boolean
}

export function LocationCard({location, ownerName, repoName, enableLinks = true}: LocationCardProps) {
  const canLink = enableLinks && !location.foundInArchive && ownerName && repoName && location.commitOid
  const urlParams = canLink
    ? {owner: ownerName, repo: repoName, commitish: location.commitOid, filePath: location.path}
    : null
  const blobUrl = urlParams ? blobPath({...urlParams, lineNumber: location.startLine}) : null
  const blameUrl = urlParams ? blamePath(urlParams) : null
  const commitUrl = canLink ? commitPath({owner: ownerName, repo: repoName, commitish: location.commitOid}) : null

  const snippetStatus = getSnippetStatus(location)

  return (
    <div className={`border rounded-2 tmp-mt-1 tmp-mb-2 overflow-hidden ${styles.LocationCard}`}>
      {/* Header: file path with copy button + kebab menu */}
      <div className="bgColor-muted d-flex flex-items-center rounded-top-2 tmp-py-1 tmp-pl-3 tmp-pr-3">
        <div className={`d-flex flex-items-center flex-1 ${styles.flexMinWidth0}`}>
          {blobUrl ? (
            <Link href={blobUrl} className={`fgColor-default text-mono f6 text-truncate ${styles.flexMinWidth0}`}>
              {location.path}
            </Link>
          ) : (
            <span className={`fgColor-muted text-mono f6 text-truncate ${styles.flexMinWidth0}`}>{location.path}</span>
          )}
          <CopyToClipboardButton className="flex-shrink-0" textToCopy={location.path} tooltipProps={{direction: 's'}} />
        </div>
        {blobUrl && (
          <ActionMenu>
            <ActionMenu.Anchor>
              <IconButton
                icon={KebabHorizontalIcon}
                variant="invisible"
                aria-label="Show file options"
                className="fgColor-muted ml-auto"
              />
            </ActionMenu.Anchor>
            <ActionMenu.Overlay>
              <ActionList>
                <ActionList.LinkItem href={blobUrl}>View file</ActionList.LinkItem>
                {blameUrl && <ActionList.LinkItem href={blameUrl}>View git blame</ActionList.LinkItem>}
              </ActionList>
            </ActionMenu.Overlay>
          </ActionMenu>
        )}
      </div>

      {/* Code snippet or fallback message */}
      {snippetStatus.show ? (
        <CodeSnippet
          startLine={location.startLine}
          endLine={location.endLine}
          startColumn={location.startColumn}
          endColumn={location.endColumn}
          blobLines={location.blobLines ?? []}
          language={location.blobLanguage ?? ''}
        />
      ) : (
        snippetStatus.reason && <p className="color-fg-muted f6 tmp-px-3 tmp-py-2">{snippetStatus.reason}</p>
      )}

      {/* Commit footer */}
      <CommitFooter
        commitOid={location.commitOid}
        commitUrl={commitUrl}
        commitMessage={location.commitMessage}
        commitCreatedAt={location.commitCreatedAt}
        commitAuthorAvatarUrl={location.commitAuthorAvatarUrl}
      />
    </div>
  )
}

function getSnippetStatus(location: LocationCardLocation): {show: boolean; reason?: string} {
  if (location.foundInArchive) return {show: false, reason: 'Previews for this file type are not available'}
  if (location.blobIsText === false) return {show: false, reason: 'Previews for binary files cannot be displayed'}
  if (location.blobIsTruncated) return {show: false, reason: 'This file is too large to show a preview'}
  if (!location.blobLines || location.blobLines.length === 0) return {show: false, reason: 'Preview not available'}
  return {show: true}
}
