import type {SafeHTMLString} from '@github-ui/safe-html'
import {VerifiedHTMLText} from '@github-ui/safe-html/VerifiedHTML'
import {clsx} from 'clsx'

import styles from './CodeSnippet.module.css'

export interface CodeSnippetProps {
  startLine: number
  endLine: number
  startColumn: number
  endColumn: number
  contextLineCount?: number
  blobLines: SafeHTMLString[]
  language: string
}

/**
 * Renders a code snippet with line numbers and column-highlighted secrets.
 * Compatible with the CodeSnippet from secret-scanning-alerts — uses the
 * same VerifiedHTMLText approach for server-colorized blob lines.
 *
 * Column-level secret highlighting is handled by the js-highlight-code-snippet-columns
 * behavior (app/assets/modules/github/behaviors/scanning.ts) which reads
 * data-start-line/end-line/start-column/end-column and wraps only the secret
 * characters in a highlight span.
 */
export function CodeSnippet({
  startLine,
  endLine,
  startColumn,
  endColumn,
  contextLineCount = 3,
  blobLines,
  language,
}: CodeSnippetProps) {
  // Server sends lines with BLOB_PADDING (5) around the match
  const offset = Math.max(1, startLine - 5)

  // Normalize columns to 1-indexed to match the alerts CodeSnippet convention
  const normalizedStartCol = startColumn === 0 && endColumn !== 0 ? 1 : startColumn + 1
  const normalizedEndCol = endColumn + 1

  return (
    <div data-testid="blob-wrapper" className={`blob-wrapper data-type-${language}`}>
      <table
        aria-label="Secret scanning alert location code snippet"
        className={clsx('js-highlight-code-snippet-columns tmp-p-2', styles.SnippetTable)}
        data-start-line={startLine}
        data-end-line={endLine}
        data-start-column={normalizedStartCol}
        data-end-column={normalizedEndCol}
      >
        <tbody aria-label="Secret scanning alert location code snippet lines">
          {blobLines.map((line, index) => {
            const lineNumber = offset + index
            if (lineNumber < startLine - contextLineCount || lineNumber > endLine + contextLineCount) return null
            return (
              <tr key={lineNumber}>
                <td
                  className={clsx('blob-num color-fg-subtle', styles.LineNumber)}
                  data-line-number={lineNumber}
                  data-testid={`blob-num-${lineNumber}`}
                />
                <td className="blob-code blob-code-inner" data-testid={`blob-code-${lineNumber}`}>
                  <VerifiedHTMLText html={line} data-line-number-content={lineNumber} />
                </td>
              </tr>
            )
          })}
        </tbody>
      </table>
    </div>
  )
}
