import type {SafeHTMLString} from '@github-ui/safe-html'

/**
 * Attribution heuristic constants — synced with TSS enum values.
 * See: token-scanning-service/ts/publicmonitoring/types.go
 */
export const AttributionHeuristic = {
  CommitAuthorEmail: 'ATTRIBUTION_HEURISTIC_COMMIT_AUTHOR_EMAIL',
} as const

export const ATTRIBUTION_LABELS: Record<string, string> = {
  [AttributionHeuristic.CommitAuthorEmail]: 'Member activity',
}

export const DEFAULT_ATTRIBUTION_LABEL = 'Attribution unknown'

/**
 * Shared alert shape — fields common to both public monitoring and ACV.
 * When we reuse these components for ACV, adapters can map ACV data into this shape.
 */
export interface SecretAlertSummary {
  secretTypeLabel: string
  rawSecret: string | null
  createdAt: string
  repositoryName: string
}

export interface PublicMonitoringAlert extends SecretAlertSummary {
  alertKey: string
  secretAuthorId: number
  slug: string
  label: string
  tokenTypeProvider: string
  validity: string
  resolution: string
  attributionHeuristic: string
  committerIdentifier: string
  committerEmail: string | null
  committerAvatarUrl: string | null
}

export interface PublicMonitoringPayload {
  alerts: PublicMonitoringAlert[]
  totalCount: number
  nextCursor: string | null
  previousCursor: string | null
}

export interface AlertLocation {
  path: string
  commitOid: string
  startLine: number
  endLine: number
  startColumn: number
  endColumn: number
  contentType: string
  createdAt: string | null
  foundInArchive: boolean
  commitMessage?: SafeHTMLString
  commitCreatedAt?: string
  commitAuthorAvatarUrl?: string
  blob?: {
    lines: SafeHTMLString[]
    language: string
    isTruncated: boolean
    isText: boolean
  }
}

export interface AlertDetailResponse {
  locations: AlertLocation[]
  totalLocationsCount: number
  locationsPerPage: number
  page: number
  repositoryOwner: string
  repositoryName: string
  commitAuthorEmail?: string | null
  committedAt?: string | null
}
