import type {ReactNode} from 'react'
import {Label, Link, RelativeTime} from '@primer/react'
import {CopyToClipboardButton} from '@github-ui/copy-to-clipboard/Button'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {ownerPath} from '@github-ui/paths'
import type {PublicMonitoringAlert} from '../types'
import {ATTRIBUTION_LABELS, DEFAULT_ATTRIBUTION_LABEL} from '../types'
import styles from './DetailMetadataTable.module.css'

interface DetailMetadataTableProps {
  alert: PublicMonitoringAlert
  commitAuthorEmail: string | null
  committedAt: string | null
}

export function DetailMetadataTable({alert, commitAuthorEmail, committedAt}: DetailMetadataTableProps) {
  // Show commit author email (from async detail response) when available,
  // fall back to user's primary email (from list payload), then username
  const emailToShow = commitAuthorEmail ?? alert.committerEmail ?? alert.committerIdentifier
  const committedDate = committedAt ?? alert.createdAt
  return (
    <div className="border rounded-2 overflow-hidden">
      {/* e.g. Fri, March 6, 2026 (2 days ago) */}
      <DetailRow label="Committed on">
        <RelativeTime datetime={committedDate} format="datetime" day="numeric" month="long" year="numeric" /> (
        <RelativeTime datetime={committedDate} />)
      </DetailRow>
      {alert.rawSecret && (
        <DetailRow label="Secret literal">
          <span className="d-flex flex-items-center gap-1">
            <span className={`text-mono wb-break-all ${styles.SecretLiteralText}`}>{alert.rawSecret}</span>
            <CopyToClipboardButton
              className="flex-shrink-0"
              textToCopy={alert.rawSecret}
              ariaLabel="Copy secret literal"
              tooltipProps={{direction: 's'}}
            />
          </span>
        </DetailRow>
      )}
      <DetailRow label="Attribution">
        <Label variant="secondary" size="small" className="bgColor-accent-muted fgColor-accent border-0 text-semibold">
          {ATTRIBUTION_LABELS[alert.attributionHeuristic] ?? DEFAULT_ATTRIBUTION_LABEL}
        </Label>
      </DetailRow>
      <DetailRow label="Committer">
        <span className="d-flex flex-items-center gap-2">
          {alert.committerAvatarUrl && (
            <GitHubAvatar alt={alert.committerIdentifier} size={20} src={alert.committerAvatarUrl} />
          )}
          <Link href={ownerPath({owner: alert.committerIdentifier})}>
            <strong>{alert.committerIdentifier}</strong>
          </Link>
        </span>
      </DetailRow>
      <DetailRow label="Committer email">
        <span className="d-flex flex-items-center gap-2">
          <span>{emailToShow}</span>
          <CopyToClipboardButton textToCopy={emailToShow} tooltipProps={{direction: 's'}} />
        </span>
      </DetailRow>
    </div>
  )
}

function DetailRow({label, children}: {label: string; children: ReactNode}) {
  return (
    <div className="d-flex flex-items-center tmp-py-2 tmp-px-3">
      <span className={`f6 text-semibold fgColor-muted text-nowrap flex-shrink-0 ${styles.DetailLabel}`}>{label}</span>
      <span className={`f6 fgColor-default wb-break-word ${styles.DetailValue}`}>{children}</span>
    </div>
  )
}
